import{_ as p,a as r,b as e,c as t,d as o,e as s,f as i,g as c}from"./chunks/dji.CFf6xt-O.js";import{_ as l,o as _,c as m,a3 as d}from"./chunks/framework.D3kUw6rp.js";const I=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"article/2025/year-end-summary/03work.md","filePath":"article/2025/year-end-summary/03work.md"}'),n={name:"article/2025/year-end-summary/03work.md"};function h(u,a,f,k,b,A){return _(),m("div",null,[...a[0]||(a[0]=[d('<h2 id="工作" tabindex="-1">工作 <a class="header-anchor" href="#工作" aria-label="Permalink to &quot;工作&quot;">​</a></h2><p>2025 年公司终于结束了萎靡不振的状态，收购事宜尘埃落地，我们的欠薪也全部到账了。</p><p><img src="'+p+'" alt=""></p><p>我们还搬离了 cocos 的革命根据地（观音山 7 号楼），来到了新的办公场地（嘉晟大厦）。</p><p>终于不用忍受那不透气的厕所和办公室了。</p><p>离开之前，编辑器小组留念一张：</p><p><img src="'+r+'" alt=""></p><p>新场地的视频：</p><video controls src="'+e+'"></video><p>从「雅基软件」 变成了 「忽然科技」。</p><h3 id="拥抱-ai" tabindex="-1">拥抱 AI <a class="header-anchor" href="#拥抱-ai" aria-label="Permalink to &quot;拥抱 AI&quot;">​</a></h3><p>新公司的产品方向就是拥抱 AI，在 vscode 的基础上构建新的 cocos creator 编辑器 （新编辑器名称叫 PinK）。</p><p>对于前端开发来说，能接触 vscode 这样量级的项目开发是非常难得的，大家都挺佩服新老板的技术战略。（如果不用 996 的话）</p><p>今年也是彻底拥抱 AI 的一年，如果没有 AI 的协助，vscode 这座大山是没那么容易就能进行二开的。</p><p>我负责 chat 模块，在 AI 编辑器中，chat 模块几乎是最重要的部分，如何与语言模型通信，如何调用工具，如何管理多模型，一切都是从零开始学习，收获颇丰。</p><p>之前甚至什么是 Agent 都不知道。</p><p>现在谈起 AI，再也不是小白的一脸茫然，感觉可以上桌吃饭了。</p><p>就是当下的工作节奏太快了，一周一个版本，压着我们 996 ，有点熬不住了，希望快点结束吧！！</p><h3 id="无心插柳" tabindex="-1">无心插柳 <a class="header-anchor" href="#无心插柳" aria-label="Permalink to &quot;无心插柳&quot;">​</a></h3><p>今年因为受不了一些网站的外链跳转提示页，顺手写了一个浏览器插件，并写了一篇文章发布到掘金，意外的爆款了。</p><p><img src="'+t+'" alt=""></p><p>文章到目前有 500+ 的赞，还收获了 70+ 的关注者。</p><p>有点运气，更有点营销的功劳，因为文章的初始标题是：</p><p><code>《浏览器插件之 - 跳过第三方链接的提示中转页》</code></p><p>阅读寥寥，于是歪脑筋一动，改了个名字：</p><p><a href="./../redirect-skipper/">《脱裤子放屁 - 你们讨厌这样的页面吗？》</a></p><p>阅读量就爆了，还被推荐到了首页</p><p><img src="'+o+'" alt=""></p><p>然后我的插件用户数一下就达到了 100 多，此时已经满足个人的小虚荣心了。</p><p>后面鬼使神差的参加了「少数派」的一个桌面比赛，为了赢得一对音响，我开始写文章去拉票。</p><p>于是把这个插件的文章也发布到「少数派」，幸运的被官方推荐了，可能是「少数派」的用户群体的特征（高端互联网群体，是的，用户群是分三六九等的，没必要扛我哈）</p><p>首先能用 chrome 浏览器且会安装插件就是过滤出一堆大人了，他们懂互联网，也更有追求，我的插件刚好只能在这样的群体里推广，属于是找到垂直用户了。在官方推荐的助澜下，插件下载量一下就超过了 1000+ ，目前已经达到 3000+ 了。有点不可思议！！</p><p><img src="'+s+'" alt=""></p><h3 id="完成延期很久的书签管理器" tabindex="-1">完成延期很久的书签管理器 <a class="header-anchor" href="#完成延期很久的书签管理器" aria-label="Permalink to &quot;完成延期很久的书签管理器&quot;">​</a></h3><p>今年还把之前一直想做的<a href="./../bookmark/">书签管理器</a>给实现了，有了 AI 的帮忙，确实很快就能完成小工具，终于把 TODO 变成 DONE 了。心中少了一块碎石。</p><p>这两款谷歌插件我都在「少数派」发了文章去做推广，幸运的是都被推荐到首页。</p><p>意外的发现被推荐首页的文章居然有稿费，于是今年就鬼使神差的赚了几百块稿费。</p><p><img src="'+i+'" alt=""></p><p>在金钱的诱惑下我把之前写的 <a href="./../../2024/blackberry/">我和黑莓</a> 也发布上去，这篇文章甚至被「少数派」发布到了它们的公众号上。</p><p>我一直思索这笔钱如何花才最有意义，必须是买个物品，这样可以更长久的留存下来，于是选了大疆的麦克风，这样我以后录制玥玥的声音可以得到更好的音质。</p><p><img src="'+c+'" alt=""></p><blockquote><p>还附加了上次公司团建老板发的 200 元京东卡</p></blockquote><p>2025 工作上差不多就这样了，此时已经是 2026-01-01 02：02 脑子有点浆糊状态了。</p>',43)])])}const P=l(n,[["render",h]]);export{I as __pageData,P as default};
